from builtins import str
import telnetlib
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.TelnetConnection import TelnetConnection
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.SshConnection import SshConnection
from taf.ul.trs_e2e_fw.lib.utils.string_format import encode_str

logger = BackgroundLogger.Instance()


class MwrTelnet(TelnetConnection):
    """
    Mwr class to perform various operations on MWR router.
    """

    TOOL = "mwr"

    def __init__(self, device, command_section):
        self.error_messages = ["%"]

        super(MwrTelnet, self).__init__(device, command_section)

    def _perform_first_login_to_switch(self):
        """
        Creates telnet session and logs in to mwr

        Returns: None

        """
        logger.info("Logging to mwr {}--".format(self.ip))
        self.communicator = telnetlib.Telnet(str(self.ip))
        logger.debug("Waiting for Password prompt")
        if "Password:" not in self.communicator.read_until("Password:", self.verification_timeout):
            raise Exception("Couldn't receive Password: prompt ")
        logger.debug("Sending Password {}".format(self.password))
        self.communicator.write((encode_str(self.password) + '\r') + "\n")
        if self.login_prompt not in self.communicator.read_until(self.login_prompt, self.verification_timeout):
            raise Exception("Couldn't receive Enable Prompt {}..Check the password sent ".format(self.login_prompt))

    def _perform_second_login_to_switch(self, prompt='#'):
        """
        Args:
            prompt: prompt in en mode

        Enters en mode in MWR

        Returns:    None
        """
        logger.debug("Sending enable command")
        self.communicator.write((encode_str("en") + '\r') + "\n")
        logger.debug("Waiting for enable password prompt")
        if "Password:" not in self.communicator.read_until("Password:", self.verification_timeout):
            raise Exception("Couldn't receive Enable Password: prompt")
        logger.debug("Sending enable  password  {}".format(self.enable_password))
        self.communicator.write((encode_str(self.enable_password) + '\r') + "\n")
        logger.debug("Sent enable password and waiting for router prompt {}".format(prompt))
        if prompt not in self.communicator.read_until(prompt, self.verification_timeout):
            raise Exception("Couldn't receive Prompt {} after sending enable password".format(prompt))

    def _execute_show_conf_command(self, prompt):
        pass

    def close_connection(self):
        """
        Close telnet session to mwr.

        Returns: None

        """
        logger.info("Closing telnet session with MWR({0})".format(self.ip))
        self.communicator.close()


class MwrSsh(SshConnection):
    TOOL = "mwr"

    def __init__(self, device, command_profile):
        """
        This methods does following :
        1. calls the parent class init method using the super.
        2. Initializes show_command for the object called.
        Args:
            device: Section name in switch in testline config file
            command_profile: Command profile name, from the switch sestion of the testline config file.

        Returns: this method is not supposed to return anything.

        """

        super(MwrSsh, self).__init__(device, command_profile)
